typedef struct Noeud {
    int valeur;
    struct Noeud *suivant;
} Noeud;

int empiler(Noeud **tete, int v)
{
    Noeud *n = malloc(sizeof *n);
    if (!n) return -1;
    n->valeur = v;
    n->suivant = *tete;
    *tete = n;
    return 0;
}

